-- Gives the initial lists in saved workspaces the category and tags they have in src/plugins/packs (v0.78.0). A list is
-- found by its id, whether or not its words were changed since. A list that already has a category or tags keeps them,
-- and a workspace that would go over the size the app saves (MaxListsBytes) is left as it is. Earlier web screens and
-- the Go server keep fields they do not know, so they keep these when they save.
WITH pack AS (
  SELECT p->>'id' AS id, p->'category' AS category, p->'tags' AS tags FROM jsonb_array_elements('[{"id":"sample-1","category":"語学","tags":["英語"]},{"id":"sample-2","category":"語学","tags":["英語"]},{"id":"un-member-states-chinese-193-beginner-1","category":"語学","tags":["中国語","国名"]},{"id":"un-member-states-chinese-193-beginner-2","category":"語学","tags":["中国語","国名"]},{"id":"un-member-states-chinese-193-intermediate","category":"語学","tags":["中国語","国名"]},{"id":"un-member-states-chinese-193-advanced-1","category":"語学","tags":["中国語","国名"]},{"id":"un-member-states-chinese-193-advanced-2","category":"語学","tags":["中国語","国名"]},{"id":"linux-commands-basic-beginner","category":"プログラミング","tags":["Linux","シェル"]},{"id":"linux-commands-basic-intermediate","category":"プログラミング","tags":["Linux","シェル"]},{"id":"linux-commands-basic-advanced","category":"プログラミング","tags":["Linux","シェル"]},{"id":"linux-commands-options-beginner","category":"プログラミング","tags":["Linux","シェル"]},{"id":"linux-commands-options-intermediate-1","category":"プログラミング","tags":["Linux","シェル"]},{"id":"linux-commands-options-intermediate-2","category":"プログラミング","tags":["Linux","シェル"]},{"id":"linux-commands-options-advanced","category":"プログラミング","tags":["Linux","シェル"]},{"id":"linux-commands-advanced-beginner","category":"プログラミング","tags":["Linux","シェル"]},{"id":"linux-commands-advanced-intermediate-1","category":"プログラミング","tags":["Linux","シェル"]},{"id":"linux-commands-advanced-intermediate-2","category":"プログラミング","tags":["Linux","シェル"]},{"id":"linux-commands-advanced-advanced","category":"プログラミング","tags":["Linux","シェル"]},{"id":"linux-shell-bash-beginner","category":"プログラミング","tags":["Linux","シェル","Bash"]},{"id":"linux-shell-bash-advanced","category":"プログラミング","tags":["Linux","シェル","Bash"]},{"id":"linux-system-beginner","category":"プログラミング","tags":["Linux"]},{"id":"linux-system-intermediate-1","category":"プログラミング","tags":["Linux"]},{"id":"linux-system-intermediate-2","category":"プログラミング","tags":["Linux"]},{"id":"linux-system-advance