,"tags":["中国語","国名"]},{"id":"un-member-states-chinese-193-lowercase-intermediate","category":"語学","tags":["中国語","国名"]},{"id":"un-member-states-chinese-193-lowercase-advanced-1","category":"語学","tags":["中国語","国名"]},{"id":"un-member-states-chinese-193-lowercase-advanced-2","category":"語学","tags":["中国語","国名"]},{"id":"postgresql-syntax-beginner","category":"プログラミング","tags":["PostgreSQL","SQL"]},{"id":"postgresql-syntax-intermediate-1","category":"プログラミング","tags":["PostgreSQL","SQL"]},{"id":"postgresql-syntax-intermediate-2","category":"プログラミング","tags":["PostgreSQL","SQL"]},{"id":"postgresql-syntax-advanced","category":"プログラミング","tags":["PostgreSQL","SQL"]},{"id":"prisma-syntax-beginner","category":"プログラミング","tags":["Prisma","TypeScript"]},{"id":"prisma-syntax-advanced","category":"プログラミング","tags":["Prisma","TypeScript"]},{"id":"jest-syntax-beginner","category":"プログラミング","tags":["Jest","テスト"]},{"id":"jest-syntax-advanced","category":"プログラミング","tags":["Jest","テスト"]},{"id":"playwright-syntax-beginner","category":"プログラミング","tags":["Playwright","テスト"]},{"id":"playwright-syntax-advanced","category":"プログラミング","tags":["Playwright","テスト"]},{"id":"typescript-syntax-beginner","category":"プログラミング","tags":["TypeScript"]},{"id":"typescript-syntax-intermediate","category":"プログラミング","tags":["TypeScript"]},{"id":"typescript-syntax-advanced","category":"プログラミング","tags":["TypeScript"]},{"id":"hono-methods-beginner","category":"プログラミング","tags":["Hono","TypeScript"]},{"id":"hono-methods-intermediate","category":"プログラミング","tags":["Hono","TypeScript"]},{"id":"hono-methods-advanced","category":"プログラミング","tags":["Hono","TypeScript"]},{"id":"php-syntax-beginner","category":"プログラミング","tags":["PHP"]},{"id":"php-syntax-intermediate","category":"プログラミング","tags":["PHP"]},{"id":"php-syntax-advanced","category":"プログラミング","tags":["PHP"]},{"id":"rails-methods-beginner","category":"プログラミング","tags":["Ruby on Rails","Ruby"]},{"id":"rails-methods-intermediate","category":"プログラミング","tags":["Ruby on Rails","Ruby"]},{"id":"rails-methods-advanced","category":"プログラミング","tags":["Ruby on Rails","Ruby"]},{"id":"express-methods-beginner","category":"プログラミング","tags":["Express","Node.js"]},{"id":"express-methods-intermediate","category":"プログラミング","tags":["Express","Node.js"]},{"id":"express-methods-advanced","category":"プログラミング","tags":["Express","Node.js"]},{"id":"oracle-plsql-syntax-beginner","category":"プログラミング","tags":["Oracle","PL/SQL","SQL"]},{"id":"oracle-plsql-syntax-intermediate","category":"プログラミング","tags":["Oracle","PL/SQL","SQL"]},{"id":"oracle-plsql-syntax-advanced","category":"プログラミング","tags":["Oracle","PL/SQL","SQL"]},{"id":"sql-server-tsql-syntax-beginner","category":"プログラミング","tags":["SQL Server","T-SQL","SQL"]},{"id":"sql-server-tsql-syntax-intermediate","category":"プログラミング","tags":["SQL Server","T-SQL","SQL"]},{"id":"sql-server-tsql-syntax-advanced","category":"プログラミング","tags":["SQL Server","T-SQL","SQL"]}]'::jsonb) p
), rebuilt AS (
  SELECT w.owner_id, jsonb_agg(
    CASE WHEN pack.id IS NOT NULL AND jsonb_typeof(saved.list) = 'object' AND saved.list->'category' IS NULL AND saved.list->'tags' IS NULL
      THEN saved.list || jsonb_build_object('category', pack.category, 'tags', pack.tags)
      ELSE saved.list END
    ORDER BY saved.position) AS lists
  FROM "typle_workspaces" w
  CROSS JOIN LATERAL jsonb_array_elements(w.lists) WITH ORDINALITY AS saved(list, position)
  LEFT JOIN pack ON pack.id = saved.list->>'id'
  WHERE jsonb_typeof(w.lists) = 'array'
  GROUP BY w.owner_id
)
UPDATE "typle_workspaces" w
SET lists = rebuilt.lists, revision = w.revision + 1, updated_at = now()
FROM rebuilt
WHERE w.owner_id = rebuilt.owner_id
  AND rebuilt.lists <> w.lists
  AND octet_length(rebuilt.lists::text) <= 896 * 1024;
